-- Rounded chrome contours stay above the wallpaper and all UI content.
-- Both windows clip their contents so the wallpaper cannot spill outside the rounded edges.
local function addTopContour(parent, z)
    local contour = Instance.new("Frame")
    contour.Name = "PhotoContour"
    contour.Size = UDim2.new(1, -4, 1, -4)
    contour.Position = UDim2.fromOffset(2, 2)
    contour.BackgroundTransparency = 1
    contour.BorderSizePixel = 0
    contour.ZIndex = z
    contour.Parent = parent
    corner(contour, 16)
    local line = Instance.new("UIStroke")
    line.Color = Color3.fromRGB(245, 245, 250)
    line.Thickness = 1.8
    line.Transparency = 0.12
    line.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
    line.Parent = contour
    return contour
end

